import numpy as np

def simulate_party_fast_small(initial_girls, initial_boys, max_steps=50000):
    girls = initial_girls
    boys = initial_boys
    for _ in range(max_steps):
        if girls == 0 and boys == 2:
            return False
        p_girl = girls / (girls + boys)
        if np.random.random() < p_girl:
            girls -= 1
            boys -= 1
        else:
            girls += 1
            boys += 1
    return True

results_small = []
for g_start in range(1, 6):
    results = [simulate_party_fast_small(g_start, g_start + 2) for _ in range(1000)]
    results_small.append(sum(results) / 1000)

print(f"Simulated probabilities of never ending for G=1 to 5:")
for i, p in enumerate(results_small):
    print(f"G={i+1}: {p:.4f} (Expected: {(i+1)/(i+2):.4f})")
